package chacha

import (
	"encoding/hex"
	"testing"
)

func TestRFC8439(t *testing.T) {
	pt := []byte("Ladies and Gentlemen of the class of '99: If I could offer you only one tip for the future, sunscreen would be it.")
	ad, _ := hex.DecodeString("50515253c0c1c2c3c4c5c6c7")
	key := make([]byte, 32)
	for i := range key {
		key[i] = 0x80 + byte(i)
	}
	nonce, _ := hex.DecodeString("070000004041424344454647")
	a, _ := New(key)
	ct := a.Seal(nil, nonce, pt, ad)
	h := hex.EncodeToString(ct)
	if h[:32] != "d31a8d34648e60db7b86afbc53ef7ec2" {
		t.Fatalf("ct %s", h)
	}
	if h[len(h)-32:] != "1ae10b594f09e26a7e902ecbd0600691" {
		t.Fatalf("tag %s", h[len(h)-32:])
	}
	out, err := a.Open(nil, nonce, ct, ad)
	if err != nil || string(out) != string(pt) {
		t.Fatal("open")
	}
	ct[0] ^= 1
	if _, err := a.Open(nil, nonce, ct, ad); err == nil {
		t.Fatal("forgery")
	}
}
EOF
