// Package hkdf implements the HMAC-based key derivation function of RFC 5869.
package hkdf

import (
	"crypto/hmac"
	"hash"
)

// Extract computes the pseudorandom key for the given salt and input keying
// material. A nil salt is replaced by a string of zeroes.
func Extract(h func() hash.Hash, secret, salt []byte) []byte {
	if salt == nil {
		salt = make([]byte, h().Size())
	}
	m := hmac.New(h, salt)
	m.Write(secret)
	return m.Sum(nil)
}

// Expand expands prk into length bytes using info.
func Expand(h func() hash.Hash, prk, info []byte, length int) []byte {
	m := hmac.New(h, prk)
	var out, prev []byte
	var counter byte = 1
	for len(out) < length {
		m.Reset()
		m.Write(prev)
		m.Write(info)
		m.Write([]byte{counter})
		prev = m.Sum(nil)
		out = append(out, prev...)
		counter++
	}
	return out[:length]
}

// Key derives length bytes of key material.
func Key(h func() hash.Hash, secret, salt, info []byte, length int) []byte {
	return Expand(h, Extract(h, secret, salt), info, length)
}
EOF
