package main

import (
	"crypto/ecdh"
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"os"
	"strings"

	"ageclone/internal/bech32"
)

func must(err error) {
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func main() {
	switch os.Args[1] {
	case "bech32":
		d, err := hex.DecodeString(os.Args[3])
		must(err)
		s, err := bech32.Encode(os.Args[2], d)
		must(err)
		fmt.Println(s)
	case "x25519":
		seed := make([]byte, 32)
		if len(os.Args) > 2 {
			var err error
			seed, err = hex.DecodeString(os.Args[2])
			must(err)
		} else {
			rand.Read(seed)
		}
		k, err := ecdh.X25519().NewPrivateKey(seed)
		must(err)
		sk, _ := bech32.Encode("AGE-SECRET-KEY-", seed)
		pk, _ := bech32.Encode("age", k.PublicKey().Bytes())
		fmt.Println("# public key: " + pk)
		fmt.Println(sk)
	case "decode":
		h, d, err := bech32.Decode(os.Args[2])
		must(err)
		fmt.Println(h, hex.EncodeToString(d))
	default:
		fmt.Println(strings.Join(os.Args, " "))
	}
}
EOF
