// Package format implements the age file header encoding.
package format

import (
	"bufio"
	"bytes"
	"encoding/base64"
	"errors"
	"fmt"
	"io"
	"strings"
)

// Stanza is a single recipient stanza in the header.
type Stanza struct {
	Type string
	Args []string
	Body []byte
}

// Header is a parsed age header.
type Header struct {
	Recipients []*Stanza
	MAC        []byte
}

var b64 = base64.RawStdEncoding.Strict()

// DecodeString decodes canonical unpadded base64, rejecting newlines.
func DecodeString(s string) ([]byte, error) {
	if strings.ContainsAny(s, "\n\r") {
		return nil, errors.New("unexpected newline character")
	}
	return b64.DecodeString(s)
}

// EncodeToString encodes as unpadded standard base64.
func EncodeToString(b []byte) string { return b64.EncodeToString(b) }

const (
	ColumnsPerLine = 64
	BytesPerLine   = ColumnsPerLine / 4 * 3
)

const Intro = "age-encryption.org/v1\n"

var (
	stanzaPrefix = []byte("->")
	footerPrefix = []byte("---")
)

// ParseError is returned for malformed headers.
type ParseError struct{ err error }

func (e *ParseError) Error() string { return "parsing age header: " + e.err.Error() }
func (e *ParseError) Unwrap() error { return e.err }

func errorf(format string, a ...interface{}) error {
	return &ParseError{fmt.Errorf(format, a...)}
}

// WrappedBase64Encoder writes base64 wrapped at ColumnsPerLine.
type WrappedBase64Encoder struct {
	enc     io.WriteCloser
	w       *wrapper
}

type wrapper struct {
	dst     io.Writer
	written int
}

func (w *wrapper) Write(p []byte) (int, error) {
	n := 0
	for len(p) > 0 {
		room := ColumnsPerLine - w.written
		chunk := p
		if len(chunk) > room {
			chunk = chunk[:room]
		}
		m, err := w.dst.Write(chunk)
		n += m
		w.written += m
		if err != nil {
			return n, err
		}
