// Package armor implements the strict PEM-like ASCII armor of age files.
package armor

import (
	"bufio"
	"bytes"
	"encoding/base64"
	"errors"
	"fmt"
	"io"

	"ageclone/internal/format"
)

const (
	Header = "-----BEGIN AGE ENCRYPTED FILE-----"
	Footer = "-----END AGE ENCRYPTED FILE-----"
)

const maxWhitespace = 1024

// MaxWhitespace is the amount of leading whitespace tolerated before the
// armor header.
const MaxWhitespace = maxWhitespace

type writer struct {
	started, closed bool
	enc             *format.WrappedBase64Encoder
	dst             io.Writer
}

// NewWriter returns a WriteCloser that armors everything written to it.
func NewWriter(dst io.Writer) io.WriteCloser {
	return &writer{dst: dst, enc: format.NewWrappedBase64Encoder(base64.StdEncoding, dst)}
}

func (a *writer) Write(p []byte) (int, error) {
	if !a.started {
		if _, err := io.WriteString(a.dst, Header+"\n"); err != nil {
			return 0, err
		}
	}
	a.started = true
	return a.enc.Write(p)
}

func (a *writer) Close() error {
	if a.closed {
		return errors.New("ArmoredWriter already closed")
	}
	a.closed = true
	if !a.started {
		if _, err := io.WriteString(a.dst, Header+"\n"); err != nil {
			return err
		}
		a.started = true
	}
	if err := a.enc.Close(); err != nil {
		return err
	}
	footer := Footer + "\n"
	if !a.enc.LastLineIsEmpty() {
		footer = "\n" + footer
	}
	_, err := io.WriteString(a.dst, footer)
	return err
}

// Error is returned for malformed armor.
type Error struct{ err error }

func (e *Error) Error() string { return "invalid armor: " + e.err.Error() }
func (e *Error) Unwrap() error { return e.err }

type reader struct {
	r       *bufio.Reader
	started bool
	unread  []byte
	buf     [format.BytesPerLine]byte
	err     error
}

// NewReader returns a reader that decodes armored data from r.
func NewReader(r io.Reader) io.Reader {
	return &reader{r: bufio.NewReader(r)}
}

func (r *reader) setErr(err error) error {
	if err != io.EOF {
		err = &Error{err}
	}
	r.err = err
	return err
}

func (r *reader) getLine() ([]byte, error) {
	line, err := r.r.ReadBytes('\n')
	if err == io.EOF && len(line) == 0 {
		return nil, io.ErrUnexpectedEOF
	} else if err != nil && err != io.EOF {
		return nil, err
	}
	line = bytes.TrimSuffix(line, []byte("\n"))
	line = bytes.TrimSuffix(line, []byte("\r"))
	return line, nil
}

func (r *reader) drainTrailing() error {
	buf, err := io.ReadAll(io.LimitReader(r.r, maxWhitespace))
	if err != nil {
		return err
	}
	if len(bytes.TrimSpace(buf)) != 0 {
		return errors.New("trailing data after armored file")
	}
	if len(buf) == maxWhitespace {
		return errors.New("too much trailing whitespace")
	}
	return io.EOF
}

func (r *reader) Read(p []byte) (int, error) {
	if len(r.unread) > 0 {
		n := copy(p, r.unread)
		r.unread = r.unread[n:]
		return n, nil
	}
	if r.err != nil {
		return 0, r.err
	}

	removed := 0
	for !r.started {
		line, err := r.getLine()
		if err != nil {
			return 0, r.setErr(err)
		}
		if len(bytes.TrimSpace(line)) == 0 {
			removed += len(line) + 1
			if removed > maxWhitespace {
				return 0, r.setErr(errors.New("too much leading whitespace"))
			}
			continue
		}
		if string(line) != Header {
			return 0, r.setErr(fmt.Errorf("invalid first line: %q", line))
		}
		r.started = true
	}

	line, err := r.getLine()
	if err != nil {
		return 0, r.setErr(err)
	}
	if string(line) == Footer {
		return 0, r.setErr(r.drainTrailing())
	}
	if len(line) == 0 {
		return 0, r.setErr(errors.New("empty line in armored data"))
	}
	if len(line) > format.ColumnsPerLine {
		return 0, r.setErr(errors.New("column limit exceeded"))
	}
	r.unread = r.buf[:]
	n, err := base64.StdEncoding.Strict().Decode(r.unread, line)
	if err != nil {
		return 0, r.setErr(err)
	}
	r.unread = r.unread[:n]

	if n < format.BytesPerLine {
		line, err := r.getLine()
		if err != nil {
			return 0, r.setErr(err)
		}
		if string(line) != Footer {
			return 0, r.setErr(fmt.Errorf("invalid closing line: %q", line))
		}
		r.setErr(r.drainTrailing())
	}

	nn := copy(p, r.unread)
	r.unread = r.unread[nn:]
	return nn, nil
}
EOF
echo ok"}

