	if w.err != nil {
		return 0, w.err
	}
	if len(p) == 0 {
		return 0, nil
	}
	total := len(p)
	for len(p) > 0 {
		free := ChunkSize - len(w.unwritten)
		if free == 0 {
			if err := w.flushChunk(false); err != nil {
				w.err = err
				return 0, err
			}
			continue
		}
		n := copy(w.buf[len(w.unwritten):ChunkSize], p)
