func (w *Writer) Close() error {
	if w.err != nil {
		return w.err
	}
	w.err = w.flushChunk(true)
	if w.err != nil {
		return w.err
	}
	w.err = errors.New("stream.Writer is already closed")
	return nil
}

func (w *Writer) flushChunk(last bool) error {
	if last {
		w.nonce.setLast()
	}
	out := w.a.Seal(nil, w.nonce[:], w.unwritten, nil)
	_, err := w.dst.Write(out)
	w.unwritten = w.buf[:0]
	w.nonce.inc()
