type poly [n]uint16

// zetas[i] = 17^BitRev7(i) mod q
var zetas [128]uint16

// gammas[i] = 17^(2*BitRev7(i)+1) mod q
var gammas [128]uint16

func init() {
	pow := func(e int) uint16 {
		r := 1
		for i := 0; i < e; i++ {
			r = r * 17 % q
		}
		return uint16(r)
	}
	for i := 0; i < 128; i++ {
		br := 0
		for b := 0; b < 7; b++ {
			if i&(1<<b) != 0 {
				br |= 1 << (6 - b)
			}
		}
		zetas[i] = pow(br)
		gammas[i] = pow(2*br + 1)
	}
}

func add(a, b uint16) uint16 {
	r := uint32(a) + uint32(b)
	if r >= q {
		r -= q
	}
	return uint16(r)
}

func sub(a, b uint16) uint16 {
	r := uint32(a) + q - uint32(b)
	if r >= q {
		r -= q
	}
	return uint16(r)
}

func mul(a, b uint16) uint16 {
	return uint16(uint32(a) * uint32(b) % q)
}

func ntt(f *poly) {
	i := 1
	for l := 128; l >= 2; l /= 2 {
		for start := 0; start < n; start += 2 * l {
			z := zetas[i]
			i++
			for j := start; j < start+l; j++ {
				t := mul(z, f[j+l])
				f[j+l] = sub(f[j], t)
				f[j] = add(f[j], t)
			}
		}
	}
