	for i := 0; i < k; i++ {
		chunk := b[384*i : 384*(i+1)]
		ek.t[i] = byteDecode(12, chunk)
		if subtle.ConstantTimeCompare(byteEncode(12, &ek.t[i]), chunk) != 1 {
