	for i := 0; i < k; i++ {
		p := mulNTT(&dk.s[i], &u[i])
		acc = polyAdd(&acc, &p)
	}
	invNTT(&acc)
	w := polySub(&v, &acc)
	for j := range w {
		w[j] = compress(1, w[j])
	}
	return byteEncode(1, &w)
