func (dk *DecapsulationKey) Decapsulate(c []byte) ([]byte, error) {
	if len(c) != CiphertextSize {
		return nil, errors.New("mlkem: invalid ciphertext length")
	}
	m := dk.decrypt(c)
	K, r := g(m, dk.h[:])
	kbar := make([]byte, 32)
	j := sha3.NewShake256()
	j.Write(dk.z[:])
	j.Write(c)
	j.Read(kbar)
	c2 := dk.ek.encrypt(m, r)
	if subtle.ConstantTimeCompare(c, c2) != 1 {
		return kbar, nil
	}
	return K, nil
}
