// Package xwing implements the X-Wing hybrid KEM (ML-KEM-768 + X25519).
package xwing

import (
	"crypto/ecdh"
	"crypto/rand"
	"errors"

	"ageclone/internal/mlkem"
	"ageclone/internal/sha3"
)

const (
	SeedSize             = 32
	EncapsulationKeySize = mlkem.EncapsulationKeySize + 32
	CiphertextSize       = mlkem.CiphertextSize + 32
	SharedKeySize        = 32
)

const label = "\\.//^\\"

// DecapsulationKey is an X-Wing private key.
type DecapsulationKey struct {
	seed [32]byte
	m    *mlkem.DecapsulationKey
	x    *ecdh.PrivateKey
	pk   []byte
}

// EncapsulationKey is an X-Wing public key.
type EncapsulationKey struct {
	m   *mlkem.EncapsulationKey
	x   *ecdh.PublicKey
	raw []byte
}

// NewDecapsulationKey expands a 32-byte seed.
func NewDecapsulationKey(seed []byte) (*DecapsulationKey, error) {
	if len(seed) != SeedSize {
		return nil, errors.New("xwing: invalid seed length")
	}
	expanded := make([]byte, 96)
	sha3.ShakeSum256(expanded, seed)
	m, err := mlkem.NewDecapsulationKeyFromSeed(expanded[:64])
	if err != nil {
		return nil, err
	}
	x, err := ecdh.X25519().NewPrivateKey(expanded[64:96])
	if err != nil {
		return nil, err
	}
	dk := &DecapsulationKey{m: m, x: x}
	copy(dk.seed[:], seed)
	dk.pk = append(m.EncapsulationKey().Bytes(), x.PublicKey().Bytes()...)
	return dk, nil
}

func (dk *DecapsulationKey) Bytes() []byte { return append([]byte(nil), dk.seed[:]...) }

// EncapsulationKey returns the public key.
func (dk *DecapsulationKey) EncapsulationKey() *EncapsulationKey {
	ek, err := NewEncapsulationKey(dk.pk)
	if err != nil {
		panic(err)
	}
	return ek
}

// NewEncapsulationKey parses a public key.
func NewEncapsulationKey(b []byte) (*EncapsulationKey, error) {
	if len(b) != EncapsulationKeySize {
		return nil, errors.New("xwing: invalid encapsulation key length")
	}
	m, err := mlkem.NewEncapsulationKey(b[:mlkem.EncapsulationKeySize])
	if err != nil {
		return nil, err
	}
	x, err := ecdh.X25519().NewPublicKey(b[mlkem.EncapsulationKeySize:])
	if err != nil {
		return nil, err
	}
	return &EncapsulationKey{m: m, x: x, raw: append([]byte(nil), b...)}, nil
}

func (ek *EncapsulationKey) Bytes() []byte { return append([]byte(nil), ek.raw...) }

func combiner(ssM, ssX, ctX, pkX []byte) []byte {
	h := sha3.New256()
	h.Write(ssM)
	h.Write(ssX)
	h.Write(ctX)
	h.Write(pkX)
	h.Write([]byte(label))
	return h.Sum(nil)
}

// Encapsulate returns a shared secret and ciphertext.
func (ek *EncapsulationKey) Encapsulate() (ss, ct []byte, err error) {
	eph, err := ecdh.X25519().GenerateKey(rand.Reader)
	if err != nil {
		return nil, nil, err
	}
	ctX := eph.PublicKey().Bytes()
	ssX, err := eph.ECDH(ek.x)
	if err != nil {
		return nil, nil, err
	}
	ssM, ctM := ek.m.Encapsulate()
	ss = combiner(ssM, ssX, ctX, ek.x.Bytes())
	return ss, append(ctM, ctX...), nil
}

// Decapsulate recovers the shared secret.
func (dk *DecapsulationKey) Decapsulate(ct []byte) ([]byte, error) {
	if len(ct) != CiphertextSize {
		return nil, errors.New("xwing: invalid ciphertext length")
	}
	ctM := ct[:mlkem.CiphertextSize]
	ctX := ct[mlkem.CiphertextSize:]
	ssM, err := dk.m.Decapsulate(ctM)
