// Package hpke implements the base mode of RFC 9180 Hybrid Public Key
// Encryption with HKDF-SHA256 and ChaCha20-Poly1305, over an arbitrary KEM.
package hpke

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/binary"

	"ageclone/internal/chacha"
)

const (
	KDFHKDFSHA256        = 0x0001
	AEADChaCha20Poly1305 = 0x0003
)

type Suite struct {
	KEM, KDF, AEAD uint16
}

func (s Suite) id() []byte {
	b := []byte("HPKE")
	b = binary.BigEndian.AppendUint16(b, s.KEM)
	b = binary.BigEndian.AppendUint16(b, s.KDF)
	b = binary.BigEndian.AppendUint16(b, s.AEAD)
	return b
}

func extract(salt, ikm []byte) []byte {
	if salt == nil {
		salt = make([]byte, sha256.Size)
	}
	m := hmac.New(sha256.New, salt)
	m.Write(ikm)
	return m.Sum(nil)
}

func expand(prk, info []byte, l int) []byte {
	m := hmac.New(sha256.New, prk)
	var out, prev []byte
	for c := byte(1); len(out) < l; c++ {
		m.Reset()
		m.Write(prev)
		m.Write(info)
		m.Write([]byte{c})
		prev = m.Sum(nil)
		out = append(out, prev...)
	}
	return out[:l]
}

func (s Suite) labeledExtract(salt []byte, label string, ikm []byte) []byte {
	in := append([]byte("HPKE-v1"), s.id()...)
	in = append(in, label...)
	in = append(in, ikm...)
	return extract(salt, in)
}

func (s Suite) labeledExpand(prk []byte, label string, info []byte, l int) []byte {
	in := binary.BigEndian.AppendUint16(nil, uint16(l))
	in = append(in, "HPKE-v1"...)
	in = append(in, s.id()...)
	in = append(in, label...)
	in = append(in, info...)
	return expand(prk, in, l)
}

// KeySchedule derives the AEAD key and base nonce for base mode.
func (s Suite) KeySchedule(sharedSecret, info []byte) (key, baseNonce []byte) {
	pskIDHash := s.labeledExtract(nil, "psk_id_hash", nil)
	infoHash := s.labeledExtract(nil, "info_hash", info)
	ctx := append([]byte{0x00}, pskIDHash...)
	ctx = append(ctx, infoHash...)
	secret := s.labeledExtract(nil, "secret", nil)
	_ = secret
	secret = s.labeledExtract(sharedSecret, "secret", nil)
	key = s.labeledExpand(secret, "key", ctx, chacha.KeySize)
	baseNonce = s.labeledExpand(secret, "base_nonce", ctx, chacha.NonceSize)
	return key, baseNonce
}

// Seal encrypts a single message (sequence number zero).
func (s Suite) Seal(sharedSecret, info, aad, pt []byte) []byte {
	key, nonce := s.KeySchedule(sharedSecret, info)
	a, _ := chacha.New(key)
	return a.Seal(nil, nonce, pt, aad)
}

// Open decrypts a single message (sequence number zero).
func (s Suite) Open(sharedSecret, info, aad, ct []byte) ([]byte, error) {
	key, nonce := s.KeySchedule(sharedSecret, info)
	a, _ := chacha.New(key)
	return a.Open(nil, nonce, ct, aad)
}
