package age

import (
	"crypto/ecdh"
	"crypto/rand"
	"crypto/sha256"
	"errors"
	"fmt"
	"strings"

	"ageclone/internal/bech32"
	"ageclone/internal/chacha"
	"ageclone/internal/format"
	"ageclone/internal/hkdf"
)

const x25519Label = "age-encryption.org/v1/X25519"

// X25519Recipient is the standard age public key.
type X25519Recipient struct {
	theirPublicKey []byte
}

func newX25519RecipientFromPoint(publicKey []byte) (*X25519Recipient, error) {
	if len(publicKey) != 32 {
		return nil, errors.New("invalid X25519 public key")
	}
	return &X25519Recipient{theirPublicKey: append([]byte(nil), publicKey...)}, nil
}

// ParseX25519Recipient parses an "age1" recipient.
func ParseX25519Recipient(s string) (*X25519Recipient, error) {
	t, k, err := bech32.Decode(s)
	if err != nil {
		return nil, fmt.Errorf("malformed recipient %q: %v", s, err)
	}
	if t != "age" {
		return nil, fmt.Errorf("malformed recipient %q: invalid type %q", s, t)
	}
	r, err := newX25519RecipientFromPoint(k)
	if err != nil {
		return nil, fmt.Errorf("malformed recipient %q: %v", s, err)
	}
	return r, nil
}

func (r *X25519Recipient) Wrap(fileKey []byte) ([]*Stanza, error) {
	eph, err := ecdh.X25519().GenerateKey(rand.Reader)
	if err != nil {
		return nil, err
	}
	ourPublicKey := eph.PublicKey().Bytes()
	pub, err := ecdh.X25519().NewPublicKey(r.theirPublicKey)
	if err != nil {
		return nil, err
	}
	sharedSecret, err := eph.ECDH(pub)
	if err != nil {
		return nil, err
	}
	l := &Stanza{
		Type: "X25519",
		Args: []string{format.EncodeToString(ourPublicKey)},
	}
	salt := make([]byte, 0, 64)
	salt = append(salt, ourPublicKey...)
	salt = append(salt, r.theirPublicKey...)
	wrappingKey := hkdf.Key(sha256.New, sharedSecret, salt, []byte(x25519Label), chacha.KeySize)
	wrapped, err := aeadEncrypt(wrappingKey, fileKey)
	if err != nil {
		return nil, err
	}
	l.Body = wrapped
	return []*Stanza{l}, nil
}

// String returns the Bech32 encoding.
func (r *X25519Recipient) String() string {
	s, _ := bech32.Encode("age", r.theirPublicKey)
	return s
}

// X25519Identity is the standard age private key.
type X25519Identity struct {
	secretKey, ourPublicKey []byte
}

func newX25519IdentityFromScalar(secretKey []byte) (*X25519Identity, error) {
	if len(secretKey) != 32 {
		return nil, errors.New("invalid X25519 secret key")
	}
	k, err := ecdh.X25519().NewPrivateKey(secretKey)
	if err != nil {
		return nil, err
	}
	return &X25519Identity{
		secretKey:    append([]byte(nil), secretKey...),
		ourPublicKey: k.PublicKey().Bytes(),
	}, nil
}

// GenerateX25519Identity creates a random identity.
func GenerateX25519Identity() (*X25519Identity, error) {
	secretKey := make([]byte, 32)
	if _, err := rand.Read(secretKey); err != nil {
		return nil, err
	}
	return newX25519IdentityFromScalar(secretKey)
}

// ParseX25519Identity parses an "AGE-SECRET-KEY-1" identity.
func ParseX25519Identity(s string) (*X25519Identity, error) {
	t, k, err := bech32.Decode(s)
	if err != nil {
		return nil, fmt.Errorf("malformed secret key: %v", err)
	}
	if t != "AGE-SECRET-KEY-" {
		return nil, fmt.Errorf("malformed secret key: unknown type %q", t)
	}
	r, err := newX25519IdentityFromScalar(k)
	if err != nil {
		return nil, fmt.Errorf("malformed secret key: %v", err)
	}
	return r, nil
}

func (i *X25519Identity) Unwrap(stanzas []*Stanza) ([]byte, error) {
	return multiUnwrap(i.unwrap, stanzas)
}

func (i *X25519Identity) unwrap(block *Stanza) ([]byte, error) {
	if block.Type != "X25519" {
		return nil, ErrIncorrectIdentity
	}
	if len(block.Args) != 1 {
		return nil, errors.New("invalid X25519 recipient block")
	}
	publicKey, err := format.DecodeString(block.Args[0])
	if err != nil {
		return nil, fmt.Errorf("failed to parse X25519 recipient: %v", err)
	}
	if len(publicKey) != 32 {
		return nil, errors.New("invalid X25519 recipient block")
	}
	priv, err := ecdh.X25519().NewPrivateKey(i.secretKey)
	if err != nil {
		return nil, err
	}
	pub, err := ecdh.X25519().NewPublicKey(publicKey)
	if err != nil {
		return nil, fmt.Errorf("invalid X25519 recipient: %v", err)
	}
	sharedSecret, err := priv.ECDH(pub)
	if err != nil {
		return nil, fmt.Errorf("invalid X25519 recipient: %v", err)
	}
	salt := make([]byte, 0, 64)
	salt = append(salt, publicKey...)
	salt = append(salt, i.ourPublicKey...)
	wrappingKey := hkdf.Key(sha256.New, sharedSecret, salt, []byte(x25519Label), chacha.KeySize)
	fileKey, err := aeadDecrypt(wrappingKey, fileKeySize, block.Body)
	if err == errIncorrectCiphertextSize {
		return nil, errors.New("invalid X25519 recipient block: incorrect file key size")
	} else if err != nil {
		return nil, ErrIncorrectIdentity
	}
	return fileKey, nil
}

// Recipient returns the public key.
func (i *X25519Identity) Recipient() *X25519Recipient {
	return &X25519Recipient{theirPublicKey: i.ourPublicKey}
}

// String returns the Bech32 encoding.
func (i *X25519Identity) String() string {
	s, _ := bech32.Encode("AGE-SECRET-KEY-", i.secretKey)
	return strings.ToUpper(s)
}
