// Package p256 parses NIST P-256 point encodings with strict validation.
package p256

import (
	"crypto/elliptic"
	"errors"
	"math/big"
)

var (
	curve = elliptic.P256()
	p     = curve.Params().P
	b     = curve.Params().B
)

func element(e []byte) (*big.Int, error) {
	x := new(big.Int).SetBytes(e)
	if x.Cmp(p) >= 0 {
		return nil, errors.New("invalid P256 element encoding")
	}
	return x, nil
}

func rhs(x *big.Int) *big.Int {
	// x^3 - 3x + b
	x3 := new(big.Int).Mul(x, x)
	x3.Mul(x3, x)
	t := new(big.Int).Lsh(x, 1)
	t.Add(t, x)
	x3.Sub(x3, t)
	x3.Add(x3, b)
	return x3.Mod(x3, p)
}

func uncompressed(x, y *big.Int) []byte {
	out := make([]byte, 65)
	out[0] = 4
	x.FillBytes(out[1:33])
	y.FillBytes(out[33:])
	return out
}

// Parse decodes a compressed or uncompressed point, returning the
// uncompressed encoding.
func Parse(enc []byte) ([]byte, error) {
	switch {
	case len(enc) == 1 && enc[0] == 0:
		return nil, errors.New("P256 point is the point at infinity")
	case len(enc) == 65 && enc[0] == 4:
		x, err := element(enc[1:33])
		if err != nil {
			return nil, err
		}
		y, err := element(enc[33:])
		if err != nil {
			return nil, err
		}
		y2 := new(big.Int).Mul(y, y)
		y2.Mod(y2, p)
		if y2.Cmp(rhs(x)) != 0 {
			return nil, errors.New("P256 point not on curve")
		}
		return uncompressed(x, y), nil
	case len(enc) == 33 && (enc[0] == 2 || enc[0] == 3):
		x, err := element(enc[1:])
		if err != nil {
			return nil, err
		}
		y := new(big.Int).ModSqrt(rhs(x), p)
		if y == nil {
			return nil, errors.New("invalid P256 compressed point encoding")
		}
		if byte(y.Bit(0)) != enc[0]&1 {
			y.Sub(p, y)
		}
		return uncompressed(x, y), nil
	default:
		return nil, errors.New("invalid P256 point encoding")
	}
}

// ParseUncompressed mimics crypto/ecdh's NewPublicKey validation.
func ParseUncompressed(enc []byte) ([]byte, error) {
	if len(enc) == 0 || enc[0] != 4 {
		return nil, errors.New("crypto/ecdh: invalid public key")
	}
	return Parse(enc)
}

// Compress returns the compressed encoding of an uncompressed point.
func Compress(u []byte) []byte {
	out := make([]byte, 33)
	out[0] = 2 | u[64]&1
	copy(out[1:], u[1:33])
	return out
}
