			l ^= nextWord(salt, &j)
			r ^= nextWord(salt, &j)
		}
		l, r = c.encryptBlock(l, r)
	}
	for i := 0; i < 18; i += 2 {
		next()
		c.p[i], c.p[i+1] = l, r
	}
