var errShortRead = errors.New("ssh: short read")

func parseString(in []byte) (out, rest []byte, ok bool) {
	if len(in) < 4 {
		return
	}
	length := binary.BigEndian.Uint32(in)
	in = in[4:]
	if uint32(len(in)) < length {
		return
	}
	out = in[:length]
	rest = in[length:]
	ok = true
	return
}

func parseUint32(in []byte) (uint32, []byte, bool) {
	if len(in) < 4 {
		return 0, nil, false
	}
	return binary.BigEndian.Uint32(in), in[4:], true
}

func parseUint64(in []byte) (uint64, []byte, bool) {
	if len(in) < 8 {
		return 0, nil, false
	}
	return binary.BigEndian.Uint64(in), in[8:], true
}

func parseInt(in []byte) (out *big.Int, rest []byte, ok bool) {
	contents, rest, ok := parseString(in)
	if !ok {
		return
	}
	out = new(big.Int)
	if len(contents) > 0 && contents[0]&0x80 == 0x80 {
		// negative number
		notBytes := make([]byte, len(contents))
		for i := range notBytes {
			notBytes[i] = ^contents[i]
		}
		out.SetBytes(notBytes)
		out.Add(out, big.NewInt(1))
		out.Neg(out)
	} else {
		out.SetBytes(contents)
	}
	ok = true
	return
}

func parseError(tag uint8) error {
	return fmt.Errorf("ssh: parse error in message type %d", tag)
}

// field kinds for the minimal unmarshaler
type fieldKind int

const (
	kString fieldKind = iota // []byte or string
	kInt                     // *big.Int
	kUint32
	kUint64
	kRest
)

// unmarshal parses fields in order, mimicking x/crypto/ssh.Unmarshal for
// structs without a message type tag.
func unmarshal(data []byte, kinds ...fieldKind) ([]interface{}, error) {
	out := make([]interface{}, len(kinds))
	for i, k := range kinds {
		switch k {
		case kString:
			s, rest, ok := parseString(data)
			if !ok {
				return nil, errShortRead
			}
			out[i] = s
			data = rest
		case kInt:
			n, rest, ok := parseInt(data)
			if !ok {
				return nil, errShortRead
			}
			out[i] = n
			data = rest
		case kUint32:
			n, rest, ok := parseUint32(data)
			if !ok {
				return nil, errShortRead
			}
			out[i] = n
			data = rest
		case kUint64:
			n, rest, ok := parseUint64(data)
			if !ok {
				return nil, errShortRead
			}
			out[i] = n
			data = rest
		case kRest:
			out[i] = data
			data = nil
		}
	}
	if len(data) != 0 {
		return nil, parseError(0)
	}
	return out, nil
}

func appendString(b []byte, s []byte) []byte {
	b = binary.BigEndian.AppendUint32(b, uint32(len(s)))
	return append(b, s...)
}

func appendInt(b []byte, n *big.Int) []byte {
	var enc []byte
	switch n.Sign() {
	case 0:
		enc = nil
	case 1:
		bs := n.Bytes()
		if bs[0]&0x80 != 0 {
			enc = append([]byte{0}, bs...)
		} else {
			enc = bs
		}
	default:
		// two's complement
		nMinus1 := new(big.Int).Neg(n)
		nMinus1.Sub(nMinus1, big.NewInt(1))
		bs := nMinus1.Bytes()
		for i := range bs {
			bs[i] ^= 0xff
		}
		if len(bs) == 0 || bs[0]&0x80 == 0 {
			bs = append([]byte{0xff}, bs...)
		}
		enc = bs
	}
	return appendString(b, enc)
}
