// PublicKey is a parsed SSH public key.
type PublicKey struct {
	typ     string
	marshal []byte
	RSA     *rsa.PublicKey
	Ed25519 ed25519.PublicKey
}

// Type returns the key type, such as "ssh-ed25519".
func (k *PublicKey) Type() string { return k.typ }

// Marshal returns the wire encoding of the key.
func (k *PublicKey) Marshal() []byte { return append([]byte(nil), k.marshal...) }

const (
	KeyAlgoRSA        = "ssh-rsa"
	KeyAlgoDSA        = "ssh-dss"
	KeyAlgoECDSA256   = "ecdsa-sha2-nistp256"
	KeyAlgoSKECDSA256 = "sk-ecdsa-sha2-nistp256@openssh.com"
	KeyAlgoECDSA384   = "ecdsa-sha2-nistp384"
	KeyAlgoECDSA521   = "ecdsa-sha2-nistp521"
	KeyAlgoED25519    = "ssh-ed25519"
	KeyAlgoSKED25519  = "sk-ssh-ed25519@openssh.com"
)

var certKeyAlgoNames = map[string]string{
	"ssh-rsa-cert-v01@openssh.com":                     KeyAlgoRSA,
	"ssh-dss-cert-v01@openssh.com":                     KeyAlgoDSA,
	"ecdsa-sha2-nistp256-cert-v01@openssh.com":         KeyAlgoECDSA256,
	"ecdsa-sha2-nistp384-cert-v01@openssh.com":         KeyAlgoECDSA384,
	"ecdsa-sha2-nistp521-cert-v01@openssh.com":         KeyAlgoECDSA521,
	"sk-ecdsa-sha2-nistp256-cert-v01@openssh.com":      KeyAlgoSKECDSA256,
	"ssh-ed25519-cert-v01@openssh.com":                 KeyAlgoED25519,
	"sk-ssh-ed25519-cert-v01@openssh.com":              KeyAlgoSKED25519,
}

func parseRSA(in []byte) (*PublicKey, []byte, error) {
	f, err := unmarshal(in, kInt, kInt, kRest)
	if err != nil {
		return nil, nil, err
	}
	e := f[0].(*big.Int)
	n := f[1].(*big.Int)
	if e.BitLen() > 24 {
		return nil, nil, errors.New("ssh: exponent too large")
	}
	ev := e.Int64()
	if ev < 3 || ev&1 == 0 {
		return nil, nil, errors.New("ssh: incorrect exponent")
	}
	pk := &rsa.PublicKey{N: n, E: int(ev)}
	m := appendString(nil, []byte(KeyAlgoRSA))
	m = appendInt(m, big.NewInt(ev))
	m = appendInt(m, n)
	return &PublicKey{typ: KeyAlgoRSA, marshal: m, RSA: pk}, f[2].([]byte), nil
}

