// ParseAuthorizedKey parses a public key from an authorized_keys file.
func ParseAuthorizedKey(in []byte) (out *PublicKey, comment string, options []string, rest []byte, err error) {
	var lastErr error
	for len(in) > 0 {
		end := bytes.IndexByte(in, '\n')
		if end != -1 {
			rest = in[end+1:]
			in = in[:end]
		} else {
			rest = nil
		}
		end = bytes.IndexByte(in, '\r')
		if end != -1 {
			in = in[:end]
		}
		in = bytes.TrimSpace(in)
		if len(in) == 0 || in[0] == '#' {
			in = rest
			continue
		}
		i := bytes.IndexAny(in, " \t")
		if i == -1 {
			in = rest
			continue
		}
		if out, comment, err = parseAuthorizedKeyFields(in[i:]); err == nil {
			return out, comment, options, rest, nil
		} else {
			lastErr = err
		}

		var b byte
		inQuote := false
		var candidateOptions []string
		optionStart := 0
		for i, b = range in {
			isEnd := !inQuote && (b == ' ' || b == '\t')
			if (b == ',' && !inQuote) || isEnd {
				if i-optionStart > 0 {
					candidateOptions = append(candidateOptions, string(in[optionStart:i]))
				}
				optionStart = i + 1
			}
			if isEnd {
				break
			}
			if b == '"' && (i == 0 || (i > 0 && in[i-1] != '\\')) {
				inQuote = !inQuote
			}
		}
		for i < len(in) && (in[i] == ' ' || in[i] == '\t') {
			i++
		}
		if i == len(in) {
			in = rest
			continue
		}
		in = in[i:]
		i = bytes.IndexAny(in, " \t")
		if i == -1 {
			in = rest
			continue
		}
		if out, comment, err = parseAuthorizedKeyFields(in[i:]); err == nil {
			options = candidateOptions
			return out, comment, options, rest, nil
		} else {
			lastErr = err
		}
		in = rest
	}
	if lastErr != nil {
		return nil, "", nil, nil, fmt.Errorf("ssh: no key found; last parsing error for ignored line: %w", lastErr)
	}
	return nil, "", nil, nil, errors.New("ssh: no key found")
}

// NewEd25519PublicKey wraps an Ed25519 public key.
func NewEd25519PublicKey(k ed25519.PublicKey) *PublicKey {
	m := appendString(nil, []byte(KeyAlgoED25519))
	m = appendString(m, k)
	return &PublicKey{typ: KeyAlgoED25519, marshal: m, Ed25519: append(ed25519.PublicKey(nil), k...)}
}

// NewRSAPublicKey wraps an RSA public key.
func NewRSAPublicKey(k *rsa.PublicKey) *PublicKey {
	m := appendString(nil, []byte(KeyAlgoRSA))
	m = appendInt(m, big.NewInt(int64(k.E)))
	m = appendInt(m, k.N)
	return &PublicKey{typ: KeyAlgoRSA, marshal: m, RSA: k}
}
