	}
	return result, err
}

func parseDSAPrivateKey(der []byte) (*dsa.PrivateKey, error) {
	var k struct {
		Version int
		P       *big.Int
		Q       *big.Int
		G       *big.Int
		Pub     *big.Int
		Priv    *big.Int
	}
	rest, err := asn1.Unmarshal(der, &k)
	if err != nil {
		return nil, errors.New("ssh: failed to parse DSA key: " + err.Error())
	}
	if len(rest) > 0 {
		return nil, errors.New("ssh: garbage after DSA key")
	}
	return &dsa.PrivateKey{
		PublicKey: dsa.PublicKey{
			Parameters: dsa.Parameters{P: k.P, Q: k.Q, G: k.G},
			Y:          k.Pub,
		},
		X: k.Priv,
	}, nil
}

const privateKeyAuthMagic = "openssh-key-v1\x00"

type openSSHDecryptFunc func(cipherName, kdfName, kdfOpts string, privKeyBlock []byte) ([]byte, error)

func unencryptedOpenSSHKey(cipherName, kdfName, kdfOpts string, privKeyBlock []byte) ([]byte, error) {
	if kdfName != "none" || cipherName != "none" {
		return nil, &PassphraseMissingError{}
	}
	if kdfOpts != "" {
		return nil, errors.New("ssh: invalid openssh private key")
	}
	return privKeyBlock, nil
}

func passphraseProtectedOpenSSHKey(passphrase []byte) openSSHDecryptFunc {
	return func(cipherName, kdfName, kdfOpts string, privKeyBlock []byte) ([]byte, error) {
		if kdfName == "none" || cipherName == "none" {
			return nil, errors.New("ssh: key is not password protected")
		}
		if kdfName != "bcrypt" {
			return nil, fmt.Errorf("ssh: unknown KDF %q, only supports %q", kdfName, "bcrypt")
		}
		f, err := unmarshal([]byte(kdfOpts), kString, kUint32)
		if err != nil {
			return nil, err
		}
		salt := f[0].([]byte)
		rounds := f[1].(uint32)
		k, err := blowfish.BcryptPBKDF(passphrase, salt, int(rounds), 32+16)
		if err != nil {
			return nil, err
		}
		key, iv := k[:32], k[32:]
		c, err := aes.NewCipher(key)
		if err != nil {
			return nil, err
		}
		switch cipherName {
		case "aes256-ctr":
			ctr := cipher.NewCTR(c, iv)
			ctr.XORKeyStream(privKeyBlock, privKeyBlock)
		case "aes256-cbc":
			if len(privKeyBlock)%c.BlockSize() != 0 {
				return nil, fmt.Errorf("ssh: invalid encrypted private key length, not a multiple of the block size")
			}
			cbc := cipher.NewCBCDecrypter(c, iv)
			cbc.CryptBlocks(privKeyBlock, privKeyBlock)
		default:
			return nil, fmt.Errorf("ssh: unknown cipher %q, only supports %q or %q", cipherName, "aes256-ctr", "aes256-cbc")
		}
		return privKeyBlock, nil
	}
}

func checkOpenSSHKeyPadding(pad []byte) error {
	for i, b := range pad {
		if int(b) != i+1 {
			return errors.New("ssh: padding not as expected")
		}
	}
	return nil
}

func parseOpenSSHPrivateKey(key []byte, decrypt openSSHDecryptFunc) (interface{}, error) {
	if len(key) < len(privateKeyAuthMagic) || string(key[:len(privateKeyAuthMagic)]) != privateKeyAuthMagic {
		return nil, errors.New("ssh: invalid openssh private key format")
	}
	remaining := key[len(privateKeyAuthMagic):]
	f, err := unmarshal(remaining, kString, kString, kString, kUint32, kString, kString)
	if err != nil {
		return nil, err
	}
	cipherName := string(f[0].([]byte))
	kdfName := string(f[1].([]byte))
	kdfOpts := string(f[2].([]byte))
	numKeys := f[3].(uint32)
	pubKey := f[4].([]byte)
	privKeyBlock := append([]byte(nil), f[5].([]byte)...)
	if numKeys != 1 {
		return nil, errors.New("ssh: multi-key files are not supported")
	}
	block, err := decrypt(cipherName, kdfName, kdfOpts, privKeyBlock)
	if err != nil {
		if perr, ok := err.(*PassphraseMissingError); ok {
			pub, errPub := ParsePublicKey(pubKey)
			if errPub != nil {
				return nil, fmt.Errorf("ssh: failed to parse embedded public key: %v", errPub)
			}
			perr.PublicKey = pub
		}
		return nil, err
	}
	pk1, err := unmarshal(block, kUint32, kUint32, kString, kRest)
	if err != nil || pk1[0].(uint32) != pk1[1].(uint32) {
		if cipherName != "none" {
			return nil, x509.IncorrectPasswordError
		}
		return nil, errors.New("ssh: malformed OpenSSH key")
	}
	keyType := string(pk1[2].([]byte))
	rest := pk1[3].([]byte)
	switch keyType {
	case KeyAlgoRSA:
		k, err := unmarshal(rest, kInt, kInt, kInt, kInt, kInt, kInt, kString, kRest)
		if err != nil {
			return nil, err
		}
		if err := checkOpenSSHKeyPadding(k[7].([]byte)); err != nil {
			return nil, err
		}
		pk := &rsa.PrivateKey{
			PublicKey: rsa.PublicKey{
				N: k[0].(*big.Int),
				E: int(k[1].(*big.Int).Int64()),
			},
			D:      k[2].(*big.Int),
			Primes: []*big.Int{k[4].(*big.Int), k[5].(*big.Int)},
		}
		if err := pk.Validate(); err != nil {
			return nil, err
		}
		pk.Precompute()
		return pk, nil
	case KeyAlgoED25519:
		k, err := unmarshal(rest, kString, kString, kString, kRest)
		if err != nil {
			return nil, err
		}
		priv := k[1].([]byte)
		if len(priv) != ed25519.PrivateKeySize {
			return nil, errors.New("ssh: private key unexpected length")
		}
		if err := checkOpenSSHKeyPadding(k[3].([]byte)); err != nil {
			return nil, err
		}
		pk := ed25519.PrivateKey(make([]byte, ed25519.PrivateKeySize))
		copy(pk, priv)
		return &pk, nil
	case KeyAlgoECDSA256, KeyAlgoECDSA384, KeyAlgoECDSA521:
		k, err := unmarshal(rest, kString, kString, kInt, kString, kRest)
		if err != nil {
			return nil, err
		}
		if err := checkOpenSSHKeyPadding(k[4].([]byte)); err != nil {
			return nil, err
		}
		curveName := string(k[0].([]byte))
		c := curveFor(curveName)
		if c == nil {
			return nil, errors.New("ssh: unhandled elliptic curve: " + curveName)
		}
		X, Y := ellipticUnmarshal(c, k[1].([]byte))
		if X == nil || Y == nil {
			return nil, errors.New("ssh: failed to unmarshal public key")
		}
		D := k[2].(*big.Int)
		if D.Cmp(c.Params().N) >= 0 {
			return nil, errors.New("ssh: scalar is out of range")
		}
		x, y := c.ScalarBaseMult(D.Bytes())
		if x.Cmp(X) != 0 || y.Cmp(Y) != 0 {
			return nil, errors.New("ssh: public key does not match private key")
		}
		return &ecdsa.PrivateKey{PublicKey: ecdsa.PublicKey{Curve: c, X: X, Y: Y}, D: D}, nil
	default:
		return nil, errors.New("ssh: unhandled key type")
	}
}
