	"ageclone/internal/chacha"
	"ageclone/internal/format"
	"ageclone/internal/hkdf"
	"ageclone/internal/sshkeys"
)

const (
	oaepLabel    = "age-encryption.org/v1/ssh-rsa"
	ed25519Label = "age-encryption.org/v1/ssh-ed25519"
)

func sshFingerprint(sshKey []byte) string {
	h := sha256.Sum256(sshKey)
	return format.EncodeToString(h[:4])
}

// RSARecipient is an ssh-rsa recipient.
type RSARecipient struct {
	sshKey *sshkeys.PublicKey
	pubKey *rsa.PublicKey
}

func NewRSARecipient(pk *sshkeys.PublicKey) (*RSARecipient, error) {
	if pk.Type() != "ssh-rsa" {
		return nil, errors.New("SSH public key is not an RSA key")
	}
	r := &RSARecipient{sshKey: pk, pubKey: pk.RSA}
	if r.pubKey.Size() < 2048/8 {
		return nil, errors.New("RSA key size is too small")
	}
	return r, nil
}

func (r *RSARecipient) Wrap(fileKey []byte) ([]*age.Stanza, error) {
	l := &age.Stanza{
		Type: "ssh-rsa",
		Args: []string{sshFingerprint(r.sshKey.Marshal())},
	}
	wrapped, err := rsa.EncryptOAEP(sha256.New(), rand.Reader, r.pubKey, fileKey, []byte(oaepLabel))
	if err != nil {
		return nil, err
	}
	l.Body = wrapped
	return []*age.Stanza{l}, nil
}

// RSAIdentity is an ssh-rsa identity.
type RSAIdentity struct {
	k      *rsa.PrivateKey
	sshKey *sshkeys.PublicKey
}

func NewRSAIdentity(key *rsa.PrivateKey) (*RSAIdentity, error) {
	return &RSAIdentity{k: key, sshKey: sshkeys.NewRSAPublicKey(&key.PublicKey)}, nil
}

func (i *RSAIdentity) Recipient() *RSARecipient {
	return &RSARecipient{sshKey: i.sshKey, pubKey: &i.k.PublicKey}
}

func (i *RSAIdentity) Unwrap(stanzas []*age.Stanza) ([]byte, error) {
	return age.MultiUnwrap(i.unwrap, stanzas)
}

func (i *RSAIdentity) unwrap(block *age.Stanza) ([]byte, error) {
	if block.Type != "ssh-rsa" {
		return nil, age.ErrIncorrectIdentity
	}
	if len(block.Args) != 1 {
		return nil, errors.New("invalid ssh-rsa recipient block")
	}
	if block.Args[0] != sshFingerprint(i.sshKey.Marshal()) {
		return nil, age.ErrIncorrectIdentity
	}
