var (
	fieldP = func() *big.Int {
		p := new(big.Int).Lsh(big.NewInt(1), 255)
		return p.Sub(p, big.NewInt(19))
	}()
	edD = func() *big.Int {
		// d = -121665/121666
		n := big.NewInt(-121665)
		d := new(big.Int).ModInverse(big.NewInt(121666), fieldP)
		n.Mul(n, d)
		return n.Mod(n, fieldP)
	}()
)

func feFromBytes(b []byte) *big.Int {
	le := make([]byte, 32)
	for i := 0; i < 32; i++ {
		le[i] = b[31-i]
	}
	le[0] &= 0x7f
	return new(big.Int).Mod(new(big.Int).SetBytes(le), fieldP)
}

func feToBytes(x *big.Int) []byte {
	be := x.FillBytes(make([]byte, 32))
	out := make([]byte, 32)
	for i := 0; i < 32; i++ {
		out[i] = be[31-i]
	}
	return out
}

func ed25519PublicKeyToCurve25519(pk ed25519.PublicKey) ([]byte, error) {
	if len(pk) != 32 {
		return nil, errors.New("edwards25519: invalid point encoding length")
	}
	y := feFromBytes(pk)
	y2 := new(big.Int).Mul(y, y)
	y2.Mod(y2, fieldP)
	u := new(big.Int).Sub(y2, big.NewInt(1))
	u.Mod(u, fieldP)
	v := new(big.Int).Mul(y2, edD)
	v.Add(v, big.NewInt(1))
	v.Mod(v, fieldP)
