	if u.Sign() != 0 {
		if v.Sign() == 0 {
			return nil, errors.New("edwards25519: invalid point encoding")
		}
		vInv := new(big.Int).ModInverse(v, fieldP)
		x2 := new(big.Int).Mul(u, vInv)
		x2.Mod(x2, fieldP)
		if big.Jacobi(x2, fieldP) != 1 {
			return nil, errors.New("edwards25519: invalid point encoding")
		}
	}
