	num := new(big.Int).Add(big.NewInt(1), y)
	den := new(big.Int).Sub(big.NewInt(1), y)
	den.Mod(den, fieldP)
	var mont *big.Int
	if den.Sign() == 0 {
		mont = big.NewInt(0)
	} else {
