}

func NewEncryptedSSHIdentity(pubKey *sshkeys.PublicKey, pemBytes []byte, passphrase func() ([]byte, error)) (*EncryptedSSHIdentity, error) {
	switch t := pubKey.Type(); t {
	case "ssh-ed25519", "ssh-rsa":
	default:
		return nil, fmt.Errorf("unsupported SSH key type: %v", t)
	}
	return &EncryptedSSHIdentity{pubKey: pubKey, pemBytes: pemBytes, passphrase: passphrase}, nil
}

