func (i *EncryptedSSHIdentity) PublicKey() *sshkeys.PublicKey { return i.pubKey }

func (i *EncryptedSSHIdentity) Unwrap(stanzas []*age.Stanza) ([]byte, error) {
	if i.decrypted != nil {
		return i.decrypted.Unwrap(stanzas)
	}
	var match bool
	for _, s := range stanzas {
		if s.Type != i.pubKey.Type() {
			continue
		}
		if len(s.Args) < 1 {
			return nil, fmt.Errorf("invalid %v recipient block", i.pubKey.Type())
		}
		if s.Args[0] != sshFingerprint(i.pubKey.Marshal()) {
			continue
		}
		match = true
		break
	}
	if !match {
		return nil, age.ErrIncorrectIdentity
	}
	passphrase, err := i.passphrase()
	if err != nil {
		return nil, fmt.Errorf("failed to obtain passphrase: %v", err)
	}
	k, err := sshkeys.ParseRawPrivateKeyWithPassphrase(i.pemBytes, passphrase)
	if err != nil {
		return nil, fmt.Errorf("failed to decrypt SSH key file: %v", err)
	}
	var matches bool
	switch k := k.(type) {
	case *ed25519.PrivateKey:
		i.decrypted, err = NewEd25519Identity(*k)
		matches = i.pubKey.Ed25519 != nil && k.Public().(ed25519.PublicKey).Equal(i.pubKey.Ed25519)
	case ed25519.PrivateKey:
		i.decrypted, err = NewEd25519Identity(k)
		matches = i.pubKey.Ed25519 != nil && k.Public().(ed25519.PublicKey).Equal(i.pubKey.Ed25519)
	case *rsa.PrivateKey:
		i.decrypted, err = NewRSAIdentity(k)
		matches = i.pubKey.RSA != nil && k.PublicKey.Equal(i.pubKey.RSA)
	default:
		return nil, fmt.Errorf("unexpected SSH key type: %T", k)
	}
	if err != nil {
		return nil, fmt.Errorf("invalid SSH key: %v", err)
	}
	if !matches {
		return nil, fmt.Errorf("mismatched private and public SSH key")
	}
	return i.decrypted.Unwrap(stanzas)
}
