// Package term provides minimal terminal handling for Linux.
package term

import (
	"io"
	"syscall"
	"unsafe"
)

func getTermios(fd uintptr) (*syscall.Termios, error) {
	var t syscall.Termios
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&t)))
	if errno != 0 {
		return nil, errno
	}
	return &t, nil
}

func setTermios(fd uintptr, t *syscall.Termios) error {
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(t)))
	if errno != 0 {
		return errno
	}
	return nil
}

// IsTerminal reports whether fd refers to a terminal.
func IsTerminal(fd uintptr) bool {
	_, err := getTermios(fd)
	return err == nil
}

type fdReader uintptr

func (r fdReader) Read(p []byte) (int, error) {
	for {
		n, err := syscall.Read(int(r), p)
		if err == syscall.EINTR {
			continue
		}
		if n < 0 {
			n = 0
		}
		if n == 0 && err == nil {
			return 0, io.EOF
		}
		return n, err
	}
}

// ReadPassword reads a line from the terminal without echo.
func ReadPassword(fd uintptr) ([]byte, error) {
	old, err := getTermios(fd)
	if err != nil {
		return nil, err
	}
	n := *old
	n.Lflag &^= syscall.ECHO
	n.Lflag |= syscall.ICANON | syscall.ISIG
	n.Iflag |= syscall.ICRNL
	if err := setTermios(fd, &n); err != nil {
		return nil, err
	}
	defer setTermios(fd, old)
	return readPasswordLine(fdReader(fd))
}

func readPasswordLine(r io.Reader) ([]byte, error) {
	var buf [1]byte
	var ret []byte
	for {
		n, err := r.Read(buf[:])
		if n > 0 {
			switch buf[0] {
			case '\b':
				if len(ret) > 0 {
					ret = ret[:len(ret)-1]
				}
			case '\n':
				return ret, nil
			case '\r':
			default:
				ret = append(ret, buf[0])
			}
			continue
		}
		if err != nil {
			if err == io.EOF && len(ret) > 0 {
				return ret, nil
			}
			return ret, err
		}
	}
}
