	t.Cflag &^= syscall.CSIZE | syscall.PARENB
	t.Cflag |= syscall.CS8
	t.Cc[syscall.VMIN] = 1
	t.Cc[syscall.VTIME] = 0
	if err := setTermios(fd, t); err != nil {
		return nil, err
	}
	return &old, nil
}

// Restore restores a previously saved terminal state.
func Restore(fd uintptr, s *State) error {
	return setTermios(fd, &s.t)
}

// ReadByte reads a single byte from fd.
func ReadByte(fd uintptr) (byte, error) {
	var b [1]byte
	n, err := fdReader(fd).Read(b[:])
	if n == 1 {
		return b[0], nil
	}
	if err == nil {
		err = io.EOF
	}
	return 0, err
}

// ReadLine reads a line in raw mode with simple echo-based line editing,
// writing the prompt and echo to out.
func ReadLine(in uintptr, out io.Writer, prompt string) (string, error) {
	out.Write([]byte(prompt))
	var line []rune
	var pending []byte
	for {
		b, err := ReadByte(in)
		if err != nil {
			return "", err
		}
		switch b {
		case '\r', '\n':
			out.Write([]byte("\r\n"))
			return string(line), nil
		case 3: // ^C
			return "", io.EOF
		case 4: // ^D
			if len(line) == 0 {
				return "", io.EOF
			}
		case 8, 127: // backspace
			if len(line) > 0 {
				line = line[:len(line)-1]
				out.Write([]byte("\x1b[D \x1b[D"))
			}
		default:
			pending = append(pending, b)
			r, size := decodeRune(pending)
			if size == 0 {
				continue
			}
			pending = pending[:0]
			if r < 32 {
				continue
			}
			line = append(line, r)
			out.Write([]byte(string(r)))
		}
	}
}

func decodeRune(p []byte) (rune, int) {
	if len(p) == 0 {
		return 0, 0
	}
	if p[0] < 0x80 {
		return rune(p[0]), 1
	}
	need := 0
	switch {
	case p[0]&0xe0 == 0xc0:
		need = 2
	case p[0]&0xf0 == 0xe0:
		need = 3
	case p[0]&0xf8 == 0xf0:
		need = 4
	default:
		return 0xfffd, 1
	}
	if len(p) < need {
		return 0, 0
	}
	return []rune(string(p[:need]))[0], need
}
