package sshkeys

import (
	"crypto/rsa"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/asn1"
	"errors"
	"math/big"
)

// The RSA private key parsing and validation below mirrors the behavior of
// recent Go versions, which validate CRT parameters strictly.

type pkcs1AdditionalRSAPrime struct {
	Prime *big.Int
	Exp   *big.Int
	Coeff *big.Int
}

type pkcs1PrivateKey struct {
	Version          int
	N                *big.Int
	E                int
	D                *big.Int
	P                *big.Int
	Q                *big.Int
	Dp               *big.Int                  `asn1:"optional"`
	Dq               *big.Int                  `asn1:"optional"`
	Qinv             *big.Int                  `asn1:"optional"`
	AdditionalPrimes []pkcs1AdditionalRSAPrime `asn1:"optional,omitempty"`
}

type ecPrivateKey struct {
	Version       int
	PrivateKey    []byte
	NamedCurveOID asn1.ObjectIdentifier `asn1:"optional,explicit,tag:0"`
	PublicKey     asn1.BitString        `asn1:"optional,explicit,tag:1"`
}

type pkcs8 struct {
	Version    int
	Algo       pkix.AlgorithmIdentifier
	PrivateKey []byte
}

var oidPublicKeyRSA = asn1.ObjectIdentifier{1, 2, 840, 113549, 1, 1, 1}

func parsePKCS1PrivateKey(der []byte) (*rsa.PrivateKey, error) {
	var priv pkcs1PrivateKey
	rest, err := asn1.Unmarshal(der, &priv)
	if len(rest) > 0 {
		return nil, asn1.SyntaxError{Msg: "trailing data"}
	}
	if err != nil {
		if _, err := asn1.Unmarshal(der, &ecPrivateKey{}); err == nil {
			return nil, errors.New("x509: failed to parse private key (use ParseECPrivateKey instead for this key format)")
		}
		if _, err := asn1.Unmarshal(der, &pkcs8{}); err == nil {
			return nil, errors.New("x509: failed to parse private key (use ParsePKCS8PrivateKey instead for this key format)")
		}
		return nil, err
	}
	if priv.Version > 1 {
		return nil, errors.New("x509: unsupported private key version")
	}
	if priv.N.Sign() <= 0 || priv.D.Sign() <= 0 || priv.P.Sign() <= 0 || priv.Q.Sign() <= 0 ||
		priv.Dp != nil && priv.Dp.Sign() <= 0 ||
		priv.Dq != nil && priv.Dq.Sign() <= 0 ||
		priv.Qinv != nil && priv.Qinv.Sign() <= 0 {
		return nil, errors.New("x509: private key contains zero or negative value")
	}
	key := new(rsa.PrivateKey)
	key.PublicKey = rsa.PublicKey{E: priv.E, N: priv.N}
	key.D = priv.D
	key.Primes = make([]*big.Int, 2+len(priv.AdditionalPrimes))
	key.Primes[0] = priv.P
	key.Primes[1] = priv.Q
	for i, a := range priv.AdditionalPrimes {
		if a.Prime.Sign() <= 0 {
			return nil, errors.New("x509: private key contains zero or negative prime")
		}
		key.Primes[i+2] = a.Prime
	}
	if len(key.Primes) == 2 {
		if priv.Dp != nil && priv.Dq != nil && priv.Qinv != nil {
			if err := checkRSAPrivateKey(key.N, key.E, key.D, priv.P, priv.Q, priv.Dp, priv.Dq, priv.Qinv); err != nil {
				return nil, err
			}
		} else if err := validateRSA(key); err != nil {
			return nil, err
		}
	} else if err := key.Validate(); err != nil {
		return nil, err
	}
	key.Precompute()
	return key, nil
}

func parsePKCS8PrivateKey(der []byte) (interface{}, error) {
	var privKey pkcs8
	if _, err := asn1.Unmarshal(der, &privKey); err == nil && privKey.Algo.Algorithm.Equal(oidPublicKeyRSA) {
		key, err := parsePKCS1PrivateKey(privKey.PrivateKey)
		if err != nil {
			return nil, errors.New("x509: failed to parse RSA private key embedded in PKCS#8: " + err.Error())
		}
		return key, nil
	}
	return x509.ParsePKCS8PrivateKey(der)
}

// validateRSA validates a two-prime key without precomputed CRT values.
func validateRSA(k *rsa.PrivateKey) error {
	N, E, D := k.N, k.E, k.D
	if N == nil {
		return errors.New("crypto/rsa: missing public modulus")
	}
	if D == nil {
		return errors.New("crypto/rsa: missing private exponent")
	}
	P, Q := k.Primes[0], k.Primes[1]
	if P == nil {
		return errors.New("crypto/rsa: prime P is nil")
	}
	if Q == nil {
		return errors.New("crypto/rsa: prime Q is nil")
	}
	if err := checkModulus(N); err != nil {
		return err
	}
	if err := checkModulus(P); err != nil {
		return err
	}
	if err := checkModulus(Q); err != nil {
		return err
	}
	if D.Cmp(N) >= 0 {
		return errors.New("input overflows the modulus")
	}
	one := big.NewInt(1)
	pm1 := new(big.Int).Sub(P, one)
	qm1 := new(big.Int).Sub(Q, one)
	if err := checkModulus(pm1); err != nil {
		return err
	}
	if err := checkModulus(qm1); err != nil {
		return err
	}
	dP := new(big.Int).Mod(D, pm1)
	dQ := new(big.Int).Mod(D, qm1)
	if P.Bit(0) == 0 {
		return errors.New("crypto/rsa: p is even")
	}
	qInv := new(big.Int).Mod(Q, P)
	qInv.Exp(qInv, new(big.Int).Sub(P, big.NewInt(2)), P)
	return checkRSAPrivateKey(N, E, D, P, Q, dP, dQ, qInv)
}

func checkModulus(m *big.Int) error {
	if m.Sign() == 0 || m.Cmp(big.NewInt(1)) == 0 {
		return errors.New("modulus must be > 1")
	}
	return nil
}

func checkRSAPublicKey(N *big.Int, E int) error {
	if N == nil {
		return errors.New("crypto/rsa: missing public modulus")
	}
	if N.Bit(0) == 0 {
		return errors.New("crypto/rsa: public modulus is even")
	}
	if E < 2 {
		return errors.New("crypto/rsa: public exponent too small or negative")
	}
	if E&1 == 0 {
		return errors.New("crypto/rsa: public exponent is even")
	}
	if E > 1<<31-1 {
		return errors.New("crypto/rsa: public exponent too large")
	}
	return nil
}

func checkRSAPrivateKey(N *big.Int, E int, D, P, Q, dP, dQ, qInv *big.Int) error {
	if err := checkRSAPublicKey(N, E); err != nil {
		return err
	}
	if P.Cmp(N) >= 0 || Q.Cmp(N) >= 0 {
		return errors.New("crypto/rsa: invalid prime")
	}
	if new(big.Int).Mul(P, Q).Cmp(N) != 0 {
		return errors.New("crypto/rsa: p * q != n")
	}
	one := big.NewInt(1)
	e := big.NewInt(int64(E))
	pm1 := new(big.Int).Sub(P, one)
	if pm1.Cmp(one) <= 0 {
		return errors.New("crypto/rsa: invalid prime")
	}
	if dP.Cmp(pm1) >= 0 {
		return errors.New("crypto/rsa: invalid CRT exponent")
	}
	if new(big.Int).Mod(new(big.Int).Mul(dP, e), pm1).Cmp(one) != 0 {
		return errors.New("crypto/rsa: invalid CRT exponent")
	}
	qm1 := new(big.Int).Sub(Q, one)
	if qm1.Cmp(one) <= 0 {
		return errors.New("crypto/rsa: invalid prime")
	}
	if dQ.Cmp(qm1) >= 0 {
		return errors.New("crypto/rsa: invalid CRT exponent")
	}
	if new(big.Int).Mod(new(big.Int).Mul(dQ, e), qm1).Cmp(one) != 0 {
		return errors.New("crypto/rsa: invalid CRT exponent")
	}
	if qInv.Cmp(P) >= 0 {
		return errors.New("crypto/rsa: invalid CRT coefficient")
	}
	if new(big.Int).Mod(new(big.Int).Mul(qInv, Q), P).Cmp(one) != 0 {
		return errors.New("crypto/rsa: invalid CRT coefficient")
	}
	return nil
}
